def canSegment(s, words):
    ws = set(words.split(","))
    lens = sorted({len(w) for w in ws})
    n = len(s)
    ok = [False] * (n + 1)
    ok[0] = True
    for i in range(1, n + 1):
        for L in lens:
            if L > i:
                break
            if ok[i - L] and s[i - L:i] in ws:
                ok[i] = True
                break
    return ok[n]
